    fn callsite_receiver_outcome_serde_default_and_excluded_from_cmp_key() {
        let cg = build_rust_call_graph(
            "struct Engine;\nimpl Engine { fn go(&self) {} }\nfn run(e: Engine) { e.go(); }\n",
        );
        let mut a = cg
