            .cloned()
            .expect("go call site");
        let b = a.clone();
        a.receiver_outcome = Some(crate::resolution_identity::ReceiverOutcome {
            key: crate::resolution_identity::ReceiverTypeKey::Bare("Engine".to_string()),
